#' Temporal delay and direction correlation based edge-lists
#'
#' `edge_delay` returns edge-lists defined by the momentary temporal delay that
#' maximizes the correlation between individual's movement directions. The
#' function expects a distance based edge-list generated by `edge_dist`, a
#' `data.table` with relocation data, individual identifiers and a window
#' argument. The window argument is used to specify the temporal window within
#' which to measure the directional correlation delay. Relocation data should be
#' in two columns representing the X and Y coordinates.
#'
#' The `edges` and `DT` must be `data.table`s. If your data is a `data.frame`,
#' you can convert it by reference using [data.table::setDT()].
#'
#' The `edges` argument expects a distance based edge-list generated with
#' `edge_dist`. The `DT` argument expects relocation data with a timegroup
#' column generated with `group_times` and a distance column generated with
#' `direction_step`.
#'
#' The rows in `edges` and `DT` are internally matched in `edge_delay` using the
#' columns `timegroup` (from `group_times`) and `ID1` and `ID2` (in `edges`,
#' from `dyad_id`) with `id` (in `DT`). This function expects a `dyadID` column,
#' generated with the `dyad_id` function. The `id`, and `direction` arguments
#' expect the names of a column in `DT` which correspond to the id, and
#' direction columns.
#'
#' @inheritParams centroid_fusion
#' @inheritParams direction_group
#' @param window temporal window in unit of timegroup column generated with
#'   `group_times`, eg. `window = 2` corresponds to the timegroups shifted by
#'   -2, -1, 0, 1, and 2 around each focal timegroup.
#'
#' @return `edge_delay` returns the input `edges` appended with a
#'   'direction_delay' column indicating the temporal delay (in units of
#'   timegroups) at which ID1's direction of movement is most similar to ID2's
#'   direction of movement within the temporal window defined, and a
#'   'direction_cor' column indicating the similarity in movement direction. The
#'   directional similarity returned in the column 'direction_cor' is the dot
#'   product of the movement directions, or equivalently, the cosine of the
#'   difference in movement directions.
#'
#'   This momentary implementation of the directional correlation delay is
#'   calculated by comparing the direction of the focal individual when dyads
#'   are within a threshold distance (set using `edge_dist`) to the neighbour
#'   individual for timegroups within the window (set using the 'window'
#'   argument).
#'
#'  Note: due to the merge required within this function, the output needs to be
#'  reassigned unlike some other `spatsoc` functions like `dyad_id`. See details
#'  in [FAQ](https://docs.ropensci.org/spatsoc/articles/faq.html).
#'
#' @export
#'
#' @references
#'
#' The directional correlation delay is defined in Nagy et al. 2010
#' (\doi{doi:10.1038/nature08891}). Nagy et al. 2010's version measures the
#' global delay across the sampling period between two individuals. This
#' function, `edge_delay`, implements the version described in Quera 2023
#' (\doi{doi:10.1111/jfb.15315}) as the momentary temporal delay that maximizes
#' the direction correlation at each timestep.
#'
#' See examples of measuring the directional correlation delay:
#'  * \doi{doi:10.1111/jfb.15315}
#'  * \doi{doi:10.1016/j.anbehav.2013.07.005}
#'  * \doi{doi:10.1073/pnas.1305552110}
#'  * \doi{doi:10.1371/journal.pcbi.1003446}
#'
#' @family Edge-list generation
#' @family Direction functions
#'
#' @examples
#' # Load data.table
#' library(data.table)
#' \dontshow{data.table::setDTthreads(1)}
#'
#' # Read example data
#' DT <- fread(system.file("extdata", "DT.csv", package = "spatsoc"))
#'
#' # Select only individuals A, B, C for this example
#' DT <- DT[ID %in% c('A', 'B', 'C')]
#'
#' # Cast the character column to POSIXct
#' DT[, datetime := as.POSIXct(datetime, tz = 'UTC')]
#'
#' # Temporal grouping
#' group_times(DT, datetime = 'datetime', threshold = '20 minutes')
#'
#' # Calculate direction
#' direction_step(
#'   DT = DT,
#'   id = 'ID',
#'   coords = c('X', 'Y'),
#'   crs = 32736
#' )
#'
#' # Distance based edge-list generation
#' edges <- edge_dist(
#'   DT,
#'   threshold = 100,
#'   id = 'ID',
#'   coords = c('X', 'Y'),
#'   timegroup = 'timegroup',
#'   returnDist = TRUE,
#'   fillNA = FALSE
#' )
#'
#' # Generate dyad id
#' dyad_id(edges, id1 = 'ID1', id2 = 'ID2')
#'
#' # Momentary temporal delay and direction correlation
#' delay <- edge_delay(
#'   edges = edges,
#'   DT = DT,
#'   window = 3,
#'   id = 'ID'
#' )
#'
#' # Or, using the new geometry interface
#' get_geometry(DT, coords = c('X', 'Y'), crs = 32736)
#' direction_step(DT, id = 'ID')
#' edges <- edge_dist(DT, threshold = 100, id = 'ID', timegroup = 'timegroup', returnDist = TRUE)
#' dyad_id(edges, id = 'ID1', id2 = 'ID2')
#' delay <- edge_delay(
#'   edges = edges,
#'   DT = DT,
#'   window = 3,
#'   id = 'ID'
#' )
edge_delay <- function(
  edges,
  DT,
  window = NULL,
  id = NULL,
  direction = 'direction',
  min_nobs = NULL
) {
  # due to NSE notes in R CMD check
  . <- timegroup <- timegroup_min <- timegroup_max <-
    timegroup_delay <- ID1 <- ID2 <- direction_delay <- direction_cor <-
      dyadID <- NULL

  assert_not_null(DT)
  assert_is_data_table(DT)
  assert_not_null(edges)
  assert_not_null(id)

  check_cols_edges <- c('ID1', 'ID2', 'timegroup')
  assert_are_colnames(edges, check_cols_edges)

  check_cols_DT <- c(id, 'timegroup', direction)
  assert_are_colnames(DT, check_cols_DT)

  assert_not_null(window)
  assert_inherits(window, 'numeric')
  assert_relation(window, `>`, 0)

  assert_col_inherits(DT, 'timegroup', 'integer')
  assert_col_inherits(edges, 'timegroup', 'integer')

  assert_not_null(min_nobs)
  assert_inherits(min_nobs, 'numeric')
  assert_relation(min_nobs, `>=`, 0)

  assert_are_colnames(edges, 'dyadID', ', did you run dyad_id?')

  assert_col_radians(DT, direction, ', did you use direction_step?')

  # "Forward": all edges ID1 -> ID2
  drop_nas <- data.table::copy(edges)[
    !(is.na(fusionID) | is.na(ID1) | is.na(ID2) | is.na(dyadID))
  ]

  forward <- drop_nas[ID1 == tstrsplit(dyadID, '-')[[1L]]]

  tg_matching <- forward[,
    {
      tg <- seq(min(timegroup), max(timegroup))
      list(
        timegroup = tg,
        ID1 = rep(ID1, length.out = length(tg)),
        ID2 = rep(ID2, length.out = length(tg))
      )
    },
    by = .(dyadID, fusionID)
  ]

  tg_matching[
    DT,
    direction_ID1 := direction,
    on = c(paste0('ID1 == ', id), 'timegroup == timegroup')
  ]
  tg_matching[
    DT,
    direction_ID2 := direction,
    on = c(paste0('ID2 == ', id), 'timegroup == timegroup')
  ]

  seq_tau <- -window:window

  if (min_nobs > 0) {
    tg_matching[,
      c('sufficient_nobs_ID1', 'sufficient_nobs_ID2') := {
        window_dir1 <- do.call(
          cbind,
          shift(direction_ID1, seq_tau, type = 'lead')
        )
        window_dir2 <- do.call(
          cbind,
          shift(direction_ID2, seq_tau, type = 'lead')
        )

        n_obs_ID1 <- apply(window_dir1, MARGIN = 1, FUN = function(x) {
          sum(!is.na(x))
        })
        n_obs_ID2 <- apply(window_dir2, MARGIN = 1, FUN = function(x) {
          sum(!is.na(x))
        })
        list(n_obs_ID1 >= min_nobs, n_obs_ID2 >= min_nobs)
      },
      by = fusionID
    ]

    tg_matching[!(sufficient_nobs_ID1), direction_ID1 := NA]
    tg_matching[!(sufficient_nobs_ID2), direction_ID2 := NA]
  }
    },
    by = fusionID
  ]

  tg_matching[!(sufficient_nobs_ID1), direction_ID1 := NA]
  tg_matching[!(sufficient_nobs_ID2), direction_ID2 := NA]

  # "Reverse": replicate forward but reverse direction ID1 <- ID2
  reverse <- data.table::copy(forward)
  data.table::setnames(reverse, c('ID1', 'ID2'), c('ID2', 'ID1'))
  reverse[, direction_delay := -direction_delay]

  out <- data.table::rbindlist(
    list(
      forward,
      reverse
    ),
    use.names = TRUE
  )

  data.table::setorder(out, timegroup)
  data.table::setcolorder(
    out,
    c('timegroup', 'ID1', 'ID2', 'dyadID')
  )

  return(out)
}
